function validate([str1, str2]) {
  if (str1.length < 1 || str1.length > 10000) return 'str1 has 1 to 10^4 characters.';
  if (str2.length < 1 || str2.length > 500) return 'str2 has 1 to 500 letters.';
  if (!/^[TF]+$/.test(str1)) return "str1 uses only 'T' and 'F'.";
  if (!/^[a-z]+$/.test(str2)) return 'str2 uses only lowercase English letters.';
  return null;
}

