function generateString(str1, str2) {
  const n = str1.length;
  const m = str2.length;
  const word = new Array(n + m - 1).fill('a');
  const fixed = new Array(n + m - 1).fill(false);
  // Each 'T' writes str2 into its window; a clash with an earlier copy means there is no answer.
  for (let i = 0; i < n; i++) {
    if (str1[i] !== 'T') continue;
    for (let j = 0; j < m; j++) {
      if (fixed[i + j] && word[i + j] !== str2[j]) return '';
      word[i + j] = str2[j];
      fixed[i + j] = true;
    }
  }
  // Each 'F' window that still spells str2 raises its last free letter from 'a' to 'b'.
  for (let i = 0; i < n; i++) {
    if (str1[i] !== 'F') continue;
    let matched = 0;
    while (matched < m && word[i + matched] === str2[matched]) matched++;
    if (matched < m) continue;
    let last = i + m - 1;
    while (last >= i && fixed[last]) last--;
    if (last < i) return '';
    word[last] = 'b';
  }
  return word.join('');
}

