function generateString(str1, str2) {
  // Depth-first search in alphabetical order, so the first complete word found is the smallest.
  // The smallest answer only needs str2's letters and the first m + 1 letters of the alphabet:
  // a free spot lies in at most m windows, and each of them can rule out only one letter there.
  const n = str1.length;
  const m = str2.length;
  const letters = [...new Set('abcdefghijklmnopqrstuvwxyz'.slice(0, m + 1) + str2)].sort();
  const word = [];
  const place = (position) => {
    if (position === n + m - 1) return true;
    for (const letter of letters) {
      word[position] = letter;
      let ok = true;
      for (let i = Math.max(0, position - m + 1); i <= Math.min(position, n - 1); i++) {
        if (str1[i] === 'T' && str2[position - i] !== letter) ok = false;
      }
      const start = position - m + 1;
      if (start >= 0 && start < n && str1[start] === 'F' && word.slice(start, position + 1).join('') === str2) ok = false;
      if (ok && place(position + 1)) return true;
    }
    return false;
  };
  return place(0) ? word.join('') : '';
}

