function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const large = size === 'large';
  // Large inputs keep n * m near 10^6, so the O(n * m) greedy stays quick in the browser.
  const [n, m] = large ? [[10000, 1], [10000, 3], [10000, 100], [2000, 500]][pick(4)] : [1 + pick(6), 1 + pick(3)];
  const letters = ['a', 'ab', 'abc', 'xyz'][pick(4)];
  const str2 = Array.from({ length: m }, () => letters[pick(letters.length)]).join('');
  if (rand() < 0.35) return [Array.from({ length: n }, () => (rand() < 0.5 ? 'T' : 'F')).join(''), str2];
  // Otherwise read str1 off a word made of copies of str2 and stray letters, so the 'T' windows agree.
  let word = '';
  while (word.length < n + m - 1) word += rand() < 0.6 ? str2 : letters[pick(letters.length)];
  const str1 = Array.from({ length: n }, (_, i) => (word.startsWith(str2, i) ? 'T' : 'F'));
  if (rand() < 0.3) str1[pick(n)] = rand() < 0.5 ? 'T' : 'F';
  return [str1.join(''), str2];
}
